import sqlite3,yaml
sm=yaml.safe_load(open('governance/stage-map.yaml'))['tables']
k=list(sm.items())[:2]; print(k)
def st(t):
    v=sm.get(t); 
    return v if isinstance(v,str) else (v or {}).get('stage') if isinstance(v,dict) else v
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
for (t,) in c.execute("select name from sqlite_master where type='table'"):
    if st(t)!='base': continue
    for f in c.execute(f'pragma foreign_key_list("{t}")'):
        if st(f[2]) not in ('base',None): print('BASE->',st(f[2]),t,f[3],'->',f[2])
        elif st(f[2]) is None: print('BASE-> ?',t,f[3],'->',f[2])
